Summary:
[{
    "SDK_name": "AppLovin SDK",
    "API_name": "setDoNotSell",
    "conditions": [
        "State laws in the United States may require users in those states to display a “Do Not Sell or Share My Personal Information” link",
        "You must set a flag for users from those states that indicates whether these users opted out",
        "If you are working directly with network partners, not all of them support MAX SDK's handling of opt-out flags"
    ],
    "effects": [
        "Helps to handle the values of users' opt-outs on behalf of some mediation partners",
        "Shares these values via adapters",
        "Helps facilitate app creators' compliance with state laws"
     ],
    "parameter_configuations": [
        {
	        "parameter_values":["true"],
	        "conditions":["A user opts out of interest-based advertising"],
	        "effects":["Indicates that a user does not want their personal information to be sold or shared"]
        },
        {
            "parameter_values":["false"],
	        "conditions":["A user does not opt out of interest-based advertising"],
	        "effects":["Indicates that a user does not object to their personal information being sold or shared"]
        }
    ]
}]
